// 只在明确新profile下构造包装器，所有旧治理调用继续使用原PoliticsGovernanceAccess。
#include "political_governance_continuation_world.hpp"
#include "political_takeover_execution_world.hpp"
#include "world_bundle.hpp"
#include "resident/domains/military/military_roster_history.hpp"
#include <limits>
namespace hanmo::resident {namespace {
FamilyDeathOriginRead life_source(const WorldBundle& w,const DynamicStepInput* phase){if(!w.family_life_enabled())return {};return [&w,phase](const StableId& actor)->Outcome<std::optional<FamilyDeathOrigin>>{auto source=phase?query_military_actor_death(w.common,w.military,actor,*phase):query_military_actor_death(w.common,w.military,actor);if(!source.ok)return {false,{},source.error};if(!source.value)return {true,std::nullopt,{}};const auto& d=*source.value;return {true,FamilyDeathOrigin{d.actor_id,d.casualty_fact_id,d.battle_id,d.tick},{}};};}
Status available(const WorldBundle& w){if(!w.catalog->political_governance_continuations||!w.political_governance_continuations||!w.governance_tasks_enabled()||!w.governance_tasks_seed_complete||!w.politics_governance_enabled()||!w.catalog->politics_governance||!w.catalog->politics_governance->enabled||!w.public_relief_enabled()||!w.catalog->organization||!w.catalog->organization->enabled||!w.catalog->local_economy||!w.political_takeover_enabled()||!w.political_takeover_seed_complete)return common_failure("GovernanceContinuationProfileRequired");return common_success();}
// 本首片没有NPC签发producer；明确本人完整提交才能生成要求永久结果绑定的记录。
Status player_guard(const WorldBundle& w,const StableId& actor){auto guard=command_common_guard(w,actor,political_governance_continue_command);if(!guard.ok)return guard;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("GovernanceContinuationPlayerCommandRequired");}
}
PoliticalGovernanceContinuationWorldAccess::PoliticalGovernanceContinuationWorldAccess(const WorldBundle& w,const PoliticalTakeoverRead& takeover,const DynamicStepInput* phase,std::unique_ptr<PoliticalGovernanceAgencyWorldAccess> agencies)
 :agencies_(std::move(agencies)),original_(w.common,w.politics,w.politics_governance,*w.catalog->politics_governance,w.organization,*w.catalog->organization,w.services,agencies_?&agencies_->read():nullptr),tasks_(w.common,w.tasks,w.governance_tasks),
 context_{w.common,w.politics,w.organization,*w.catalog->organization,w.local_economy,w.services,original_,tasks_,takeover,*w.political_governance_continuations,life_source(w,phase),phase},access_(context_){}
Outcome<std::unique_ptr<PoliticalGovernanceContinuationWorldAccess>> PoliticalGovernanceContinuationWorldAccess::create(const WorldBundle& w,const PoliticalTakeoverRead& takeover,const DynamicStepInput* phase){auto ready=available(w);if(!ready.ok)return {false,{},ready.error};if(phase&&(w.common.tick()<0||w.common.tick()==std::numeric_limits<Integer>::max()||phase->from_tick!=w.common.tick()||phase->to_tick!=w.common.tick()+1))return {false,{},common_failure("GovernanceContinuationPhaseMismatch").error};auto agencies=PoliticalGovernanceAgencyWorldAccess::create(w,phase);if(!agencies.ok)return {false,{},agencies.error};return {true,std::unique_ptr<PoliticalGovernanceContinuationWorldAccess>{new PoliticalGovernanceContinuationWorldAccess(w,takeover,phase,std::move(agencies.value))},{}};}
// World末位在完整原军事、Task、治理及赈济之后调用；不用新许可替代那些原来源全验。
Status validate_political_governance_continuation_world(const WorldBundle& w){auto layout=validate_political_governance_continuation_layout(w.common,w.catalog->identity.module_versions,w.catalog->political_governance_continuations,w.political_governance_continuations?&*w.political_governance_continuations:nullptr);if(!layout.ok)return layout;if(!w.catalog->political_governance_continuations)return common_success();auto takeover=PoliticalTakeoverExecutionWorldAccess::create(w);if(!takeover.ok)return {false,{},takeover.error};if(!takeover.value->responsibilities())return common_failure("GovernanceContinuationTakeoverUnavailable");auto read=PoliticalGovernanceContinuationWorldAccess::create(w,*takeover.value->responsibilities());if(!read.ok)return {false,{},read.error};auto valid=validate_political_governance_continued_execution(read.value->context(),w.governance_tasks,w.public_relief);if(!valid.ok)return valid;return validate_political_governance_continuation_results(w.common,*w.political_governance_continuations,[](const CommitResult& r){return r.details&&std::holds_alternative<Done>(r.details->data);});}
Outcome<PoliticalGovernanceContinuationQuote> prepare_political_governance_continuation_world(const WorldBundle& w,const StableId& actor,const PoliticalContinueGovernance& command){auto guard=player_guard(w,actor);if(!guard.ok)return {false,{},guard.error};auto takeover=PoliticalTakeoverExecutionWorldAccess::create(w);if(!takeover.ok)return {false,{},takeover.error};if(!takeover.value->responsibilities())return {false,{},common_failure("GovernanceContinuationTakeoverUnavailable").error};auto read=PoliticalGovernanceContinuationWorldAccess::create(w,*takeover.value->responsibilities());if(!read.ok)return {false,{},read.error};return preview_political_governance_continuation(read.value->context(),actor,command);}
Outcome<StableId> commit_political_governance_continuation_world(WorldBundle& w,const StableId& actor,const PoliticalContinueGovernance& command,const PoliticalGovernanceContinuationQuote& quote){auto guard=player_guard(w,actor);if(!guard.ok)return {false,{},guard.error};auto takeover=PoliticalTakeoverExecutionWorldAccess::create(w);if(!takeover.ok)return {false,{},takeover.error};if(!takeover.value->responsibilities())return {false,{},common_failure("GovernanceContinuationTakeoverUnavailable").error};auto read=PoliticalGovernanceContinuationWorldAccess::create(w,*takeover.value->responsibilities());if(!read.ok)return {false,{},read.error};return apply_political_governance_continuation_in_candidate(w.common,*w.political_governance_continuations,read.value->context(),actor,command,quote);}
Outcome<BoundaryValue> query_political_governance_continuation_world(const WorldBundle& w,const StableId& place,Integer cursor){auto takeover=PoliticalTakeoverExecutionWorldAccess::create(w);if(!takeover.ok)return {false,{},takeover.error};if(!takeover.value->responsibilities())return {false,{},common_failure("GovernanceContinuationTakeoverUnavailable").error};auto read=PoliticalGovernanceContinuationWorldAccess::create(w,*takeover.value->responsibilities());if(!read.ok)return {false,{},read.error};return query_political_governance_continuations(read.value->context(),w.governance_tasks,place,cursor);}
}
